'use strict';
(async()=>{
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),size=n=>n>=1e9?(n/1e9).toFixed(2)+' GB':n>=1e6?(n/1e6).toFixed(1)+' MB':n>=1000?(n/1000).toFixed(1)+' KB':n+' B';
const params=new URLSearchParams(location.search),opened=new Map();let catalog,section=params.get('section')||'decrypted',folder=params.get('folder')||'',page=0,filtered=[],chosen=null,folderRows=[],generation=0,previewURL;
const perPage=50,save=(blob,name)=>{const u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),30000)};
const inFolder=r=>r.section===section&&r.path.startsWith(folder),archiveURL=name=>catalog.releaseBase+encodeURIComponent(name);
function sync(){document.querySelectorAll('[data-section]').forEach(b=>b.classList.toggle('active',b.dataset.section===section));const q=$('#query').value.toLowerCase().trim();filtered=catalog.files.filter(r=>inFolder(r)&&(!q||($('#scope').value==='name'?r.path.split('/').pop():r.path).toLowerCase().includes(q)));page=0;
 const children=new Map();for(const r of catalog.files.filter(inFolder)){const remaining=r.path.slice(folder.length);if(remaining.includes('/')){const name=remaining.split('/')[0];children.set(name,(children.get(name)||0)+1)}}
 $('#folders').innerHTML=[...children].sort().map(([n,c])=>`<button data-folder="${esc(folder+n+'/')}">▸ ${esc(n)} <small>(${c})</small></button>`).join('');
 const parts=folder.split('/').filter(Boolean);$('#breadcrumbs').innerHTML='<button data-folder="">All folders</button>'+parts.map((s,i)=>`<span>/</span><button data-folder="${esc(parts.slice(0,i+1).join('/')+'/')}">${esc(s)}</button>`).join('');
 $('#status').textContent=`${filtered.length.toLocaleString()} files · ${size(filtered.reduce((n,r)=>n+r.bytes,0))} · includes subfolders`;
 history.replaceState(null,'','?'+new URLSearchParams({section,folder,q:$('#query').value,scope:$('#scope').value}));render();}
function render(){$('#files').innerHTML=filtered.slice(page*perPage,(page+1)*perPage).map((r,i)=>`<button data-file="${i}" class="${chosen===r?'active':''}"><span>${esc(r.path.split('/').pop())}<small>${esc(r.path)}</small></span><small>${size(r.bytes)}</small></button>`).join('')||'<p>No matching files.</p>';$('#page').textContent=`${filtered.length?page+1:0} / ${Math.ceil(filtered.length/perPage)}`;$('#prev').disabled=page===0;$('#next').disabled=(page+1)*perPage>=filtered.length;}
async function content(r){if(r.url){const response=await fetch(r.url);if(!response.ok)throw Error('File download failed');return response.blob()}const file=opened.get(r.archive);if(!file)throw Error('Download and open '+r.archive+' first.');if(r.offset+r.bytes>file.size)throw Error('Archive size mismatch. Use the archive linked above.');const blob=file.slice(r.offset,r.offset+r.bytes);const actual=[...new Uint8Array(await crypto.subtle.digest('SHA-256',await blob.arrayBuffer()))].map(n=>n.toString(16).padStart(2,'0')).join('');if(actual!==r.sha256)throw Error('File verification failed: this archive does not match the catalog.');return blob}
async function select(r){chosen=r;const p=new URLSearchParams(location.search);p.set('file',r.path);history.replaceState(null,'','?'+p);const ticket=++generation;render();if(previewURL){URL.revokeObjectURL(previewURL);previewURL=null}$('#detail').innerHTML=`<h2>${esc(r.path.split('/').pop())}</h2><p>${esc(r.path)}</p><p>${size(r.bytes)} · ${esc(r.kind)}</p><div class="actions">${r.url?`<a href="${esc(r.url)}" download>Download file</a>`:`<a href="${esc(archiveURL(r.archive))}">Download containing archive ↗</a><button id="save-file" ${opened.has(r.archive)?'':'disabled'}>Download this file</button>`}<button id="save-metadata">Download file info JSON</button></div>${r.archive?`<p>Archive: ${esc(r.archive)}. ${opened.has(r.archive)?'Opened locally.':'After downloading, open it below to extract this file without uploading anything.'}</p>`:''}<p id="file-message" role="status"></p><div id="preview"></div>`;
 $('#save-metadata').onclick=()=>save(new Blob([JSON.stringify(r,null,2)],{type:'application/json'}),r.path.split('/').pop()+'.info.json');if($('#save-file'))$('#save-file').onclick=async()=>{try{$('#file-message').textContent='Verifying file…';save(await content(r),r.path.split('/').pop());$('#file-message').textContent='File verified and download started.'}catch(e){$('#file-message').textContent=e.message}};
 if((r.url||opened.has(r.archive))&&r.bytes<2e6){try{const blob=await content(r);if(ticket!==generation)return;if(/\.(json|lua|txt|csv|md|xml|yml|yaml)$/i.test(r.path)){const pre=document.createElement('pre');pre.textContent=await blob.text();if(ticket===generation)$('#preview').append(pre)}else if(/\.(png|webp|jpg|jpeg)$/i.test(r.path)){previewURL=URL.createObjectURL(blob);$('#preview').innerHTML=`<img src="${previewURL}" alt="File preview">`}}catch(e){if(ticket===generation)$('#file-message').textContent=e.message}}
}
// Stored ZIP writer: preserves folder paths and avoids external dependencies.
const crcTable=Uint32Array.from({length:256},(_,n)=>{for(let k=0;k<8;k++)n=(n>>>1)^((n&1)?0xedb88320:0);return n>>>0});
function crc32(bytes){let c=0xffffffff;for(const b of bytes)c=crcTable[(c^b)&255]^(c>>>8);return (c^0xffffffff)>>>0}
async function folderZip(rows){const parts=[],central=[];let offset=0,centralSize=0;const encoder=new TextEncoder();for(let i=0;i<rows.length;i++){const r=rows[i];$('#folder-status').textContent=`Preparing ${i+1} / ${rows.length}…`;const bytes=new Uint8Array(await (await content(r)).arrayBuffer()),name=encoder.encode(r.path),crc=crc32(bytes),h=new Uint8Array(30),v=new DataView(h.buffer);v.setUint32(0,0x04034b50,true);v.setUint16(4,20,true);v.setUint16(6,2048,true);v.setUint32(14,crc,true);v.setUint32(18,bytes.length,true);v.setUint32(22,bytes.length,true);v.setUint16(26,name.length,true);parts.push(h,name,bytes);const c=new Uint8Array(46),d=new DataView(c.buffer);d.setUint32(0,0x02014b50,true);d.setUint16(4,20,true);d.setUint16(6,20,true);d.setUint16(8,2048,true);d.setUint32(16,crc,true);d.setUint32(20,bytes.length,true);d.setUint32(24,bytes.length,true);d.setUint16(28,name.length,true);d.setUint32(42,offset,true);central.push(c,name);centralSize+=46+name.length;offset+=30+name.length+bytes.length;}const e=new Uint8Array(22),v=new DataView(e.buffer);v.setUint32(0,0x06054b50,true);v.setUint16(8,rows.length,true);v.setUint16(10,rows.length,true);v.setUint32(12,centralSize,true);v.setUint32(16,offset,true);return new Blob([...parts,...central,e],{type:'application/zip'})}
try{const response=await fetch('data/file-catalog.json');if(!response.ok)throw Error('Catalog unavailable');catalog=await response.json();if(!['decrypted','unencrypted','encrypted','unknown','exports'].includes(section))section='decrypted';$('#query').value=params.get('q')||'';$('#scope').value=params.get('scope')==='path'?'path':'name';
 // Source links carry a complete bundle path, so start in its matching section.
 if(params.has('q')&&!params.has('section')){const hit=catalog.files.find(r=>r.path===params.get('q'));if(hit){section=hit.section;$('#scope').value='path'}}sync();if(params.has('file')){const r=catalog.files.find(r=>r.section===section&&r.path===params.get('file'));if(r)select(r)}
 let timer;$('#query').oninput=()=>{clearTimeout(timer);timer=setTimeout(sync,180)};$('#scope').onchange=sync;document.querySelectorAll('[data-section]').forEach(b=>b.onclick=()=>{section=b.dataset.section;folder='';sync()});for(const id of ['folders','breadcrumbs'])$('#'+id).onclick=e=>{const b=e.target.closest('[data-folder]');if(b){folder=b.dataset.folder;sync()}};
 $('#files').onclick=e=>{const b=e.target.closest('[data-file]');if(b)select(filtered[page*perPage+Number(b.dataset.file)])};$('#prev').onclick=()=>{page--;render()};$('#next').onclick=()=>{page++;render()};
 $('#archive-input').onchange=()=>{let rejected=0;for(const f of $('#archive-input').files){const expected=catalog.archives.find(a=>a.name===f.name);if(expected&&expected.bytes===f.size)opened.set(f.name,f);else rejected++}$('#archive-status').textContent=`${opened.size} archive(s) opened locally.${rejected?' '+rejected+' unrecognized or wrong-size archive(s) skipped.':''} Files are verified when extracted.`;if(chosen)select(chosen)};
 $('#folder-download').onclick=()=>{folderRows=catalog.files.filter(inFolder);const names=[...new Set(folderRows.map(r=>r.archive).filter(Boolean))],total=folderRows.reduce((n,r)=>n+r.bytes,0);$('#folder-info').textContent=`${folder||section}: ${folderRows.length.toLocaleString()} files, ${size(total)}. Search filters do not limit folder downloads. Packages may also include neighboring folders; together they include every file in this folder.`;$('#archive-links').innerHTML=names.map(n=>`<a href="${esc(archiveURL(n))}">Download ${esc(n)} · ${size(catalog.archives.find(a=>a.name===n).bytes)}</a>`).join('')||'<p>These files are hosted directly. Save a folder ZIP below.</p>';if(!names.length&&total>250*1024*1024){const chunks=[];let chunk=[],bytes=0;for(const r of folderRows){if(chunk.length&&(bytes+r.bytes>200*1024*1024||chunk.length>=60000)){chunks.push(chunk);chunk=[];bytes=0}chunk.push(r);bytes+=r.bytes}if(chunk.length)chunks.push(chunk);$('#archive-links').innerHTML='<p>Download this large folder in ZIP parts. Each part preserves the original paths.</p>'+chunks.map((rs,i)=>`<button data-export-part="${i}">Save folder ZIP part ${i+1} / ${chunks.length} · ${size(rs.reduce((n,r)=>n+r.bytes,0))}</button>`).join('');document.querySelectorAll('[data-export-part]').forEach(b=>b.onclick=async()=>{b.disabled=true;try{save(await folderZip(chunks[Number(b.dataset.exportPart)]),(folder.split('/').filter(Boolean).pop()||section)+'-part-'+(Number(b.dataset.exportPart)+1)+'.zip');$('#folder-status').textContent='ZIP part download started.'}catch(e){$('#folder-status').textContent=e.message}finally{b.disabled=false}})}const ready=folderRows.length>0&&total<=250*1024*1024&&folderRows.length<65535&&names.every(n=>opened.has(n));$('#exact-folder').disabled=!ready;$('#folder-status').textContent=total>250*1024*1024?'For large folders, download the archive parts above or choose a smaller subfolder.':ready?'Ready to save the exact folder.':'Open the listed archives below to save an exact subfolder ZIP.';$('#folder-dialog').showModal()};
 $('#exact-folder').onclick=async()=>{$('#exact-folder').disabled=true;try{save(await folderZip(folderRows),(folder.split('/').filter(Boolean).pop()||section)+'.zip');$('#folder-status').textContent='Folder ZIP download started.'}catch(e){$('#folder-status').textContent=e.message}finally{$('#exact-folder').disabled=false}};$('#close-folder').onclick=()=>$('#folder-dialog').close();
 $('#release-status').innerHTML=catalog.releasePublished?`Archives: <a href="${esc(catalog.releaseURL)}">GitHub Release ↗</a>`:'Release archives are prepared but not published yet. Direct website-export downloads and opening local archives already work; GitHub archive links activate after publication.';
}catch(e){$('#status').textContent='Unable to load files: '+e.message}
})();
